import { bump, f, x, y } from "core";

console.log("ext evaluates; f() =", f());
function probe(read) {
  try {
    return String(read());
  } catch (e) {
    return `${e.name}: ${e.message}`;
  }
}
export const early = `${probe(() => x)} | ${probe(() => y)}`;

export function later() {
  return `x=${x} y=${y}`;
}

export function bumpFromIsland() {
  return `bump=${bump()} x=${x}`;
}
